// Monta o lembrete que vai para o CLIENTE, e que pede confirmacao sim/nao.
// A resposta dele entra pelo workflow 05 e vira agendamento.confirmado ou
// agendamento.cancelado.
//
// Por que a janela de 5 minutos do gatilho nao atrasa nada que importe: a regua
// e 'avisa 2h antes'. Cinco minutos de imprecisao em cima de duas horas e
// irrelevante para o cliente, e corta 80% das execucoes em relacao a rodar a
// cada minuto. O vault registra que foi exatamente o custo por execucao que
// decidiu self-hosted em vez de Make/Zapier — a regua e alto volume de tarefa
// barata, e aqui esse custo aparece.

const FUSO = $env.FUSO_PADRAO || 'America/Sao_Paulo';

function quando(iso) {
  const d = new Date(iso);
  return {
    data: new Intl.DateTimeFormat('pt-BR', {
      timeZone: FUSO, day: '2-digit', month: '2-digit',
    }).format(d),
    hora: new Intl.DateTimeFormat('pt-BR', {
      timeZone: FUSO, hour: '2-digit', minute: '2-digit', hour12: false,
    }).format(d),
  };
}

const saida = [];

for (const item of $input.all()) {
  const l = item.json;
  // reservar_lembretes_devidos devolve o contexto na coluna 'contexto_do_agendamento'
  const d = l.contexto_do_agendamento || l.dados || {};
  const t = quando(d.inicio_em);

  // Em cima da hora o texto muda: 'em 2 horas' seria mentira quando o
  // agendamento foi marcado para daqui a 20 minutos, e a regua manda avisar na
   // hora nesse caso (ver agendar_lembrete em 0011).
  const minutosAte = Math.round((new Date(d.inicio_em).getTime() - Date.now()) / 60000);
  const emCimaDaHora = minutosAte <= 150;

  saida.push({
    json: {
      lembrete_id: l.id,
      owner_id: l.owner_id,
      canal: l.canal,
      destino: l.destino,
      template: emCimaDaHora ? 'lembrete_cliente_agora' : 'lembrete_cliente_2h',
      variaveis: {
        cliente: (d.cliente && d.cliente.nome) || 'tudo bem',
        loja: (d.barbearia && d.barbearia.nome) || 'a barbearia',
        servico: (d.servico && d.servico.nome) || 'seu servico',
        profissional: (d.profissional && d.profissional.nome) || '',
        data: t.data,
        hora: t.hora,
      },
      // Dedupe pelo id do lembrete: a linha e unica por (appointment_id, tipo),
      // entao remarcar reaproveita a linha e NAO gera mensagem nova com chave
      // nova. E isso que mantem uma mensagem por agendamento.
      chave_dedupe: `lembrete:${l.id}`,
    },
  });
}

return saida;
